import java.util.*;
public class DiseaseProbe {
    public static void main(String[] a) {
        Randomizer.reset();
        SimulationEngine engine = new SimulationEngine(160, 240);
        engine.reset(); // populate only, no steps
        Field f = engine.getField();
        List<Disease> diseases = new ArrayList<>();
        Set<String> distinctRates = new TreeSet<>();
        for (int r = 0; r < f.getDepth(); r++)
            for (int c = 0; c < f.getWidth(); c++) {
                Object o = f.getObjectAt(r, c);
                if (o instanceof Organism && ((Organism) o).isDiseased()) {
                    Disease d = ((Organism) o).getDisease();
                    diseases.add(d);
                    distinctRates.add(String.format("%.4f/%.4f", d.getPropagationRate(), d.getLethalityRate()));
                }
            }
        System.out.println("diseased organisms after populate = " + diseases.size());
        System.out.println("distinct (propagation/lethality) pairs = " + distinctRates.size());
        System.out.println("sample rates: " + distinctRates);
    }
}
